# Verify script 9 leaves private row diagnostics and only aggregate conflict counts in output.
suppressPackageStartupMessages({library(dplyr);library(tidyr);library(readr);library(lubridate)})
source("utils/culture_core.R")
scratch<-tempfile("ast_linkage_failure_");dir.create(scratch)
tables<-file.path(scratch,"tables");dir.create(tables)
run<-"fixture";private<-file.path(scratch,"data","intermediate","runs",run,"cohort");dir.create(private,recursive=TRUE)
h<-tibble(patient_id=c("p1","p2"),hospitalization_id=c("h1","h2"),admission_dttm=as.POSIXct("2020-01-01",tz="UTC"),discharge_dttm=as.POSIXct("2020-01-04",tz="UTC"),age_at_admission=55)
adt<-transmute(h,hospitalization_id,in_dttm=admission_dttm,out_dttm=discharge_dttm,location_category="icu")
micro<-transmute(h,patient_id,hospitalization_id,organism_id="reused",order_dttm=admission_dttm,collect_dttm=admission_dttm+3600,result_dttm=admission_dttm+7200,organism_name="E. coli",organism_category="escherichia_coli",organism_group="escherichia",fluid_name="blood",fluid_category="blood_buffy",method_name="culture",method_category="culture")
for(name in c("hospitalization","adt","microbiology_culture"))write_csv(switch(name,hospitalization=h,adt=adt,microbiology_culture=micro),file.path(tables,paste0("clif_",name,".csv")))
write_csv(tibble(organism_id="reused",antimicrobial_category="ceftriaxone",susceptibility_category="susceptible"),file.path(tables,"clif_microbiology_susceptibility.csv"))
write_csv(build_culture_data(h,adt,micro)$rows,file.path(private,"icu_culture_rows_fixture.csv"))
dir.create(file.path(scratch,"config","mcide"),recursive=TRUE)
file.copy(list.files("config/mcide",full.names=TRUE),file.path(scratch,"config","mcide"))
config<-file.path(scratch,"config.json");jsonlite::write_json(list(site_name="TEST",repo=scratch,tables_path=tables,file_type="csv"),config,auto_unbox=TRUE)
Sys.setenv(CLIF_CONFIG_PATH=config,CLIF_RUN_ID=run,CLIF_REPO=scratch);Sys.unsetenv(c("CLIF_TABLES_PATH","CLIF_SITE_NAME"))
log<-file.path(scratch,"failure.log")
status<-suppressWarnings(system2(file.path(R.home("bin"),"Rscript"),"code/09_susceptibility_trends.R",stdout=log,stderr=log))
stopifnot(status!=0)
output<-file.path(scratch,"output","runs",run,"susceptibility")
summary<-read_csv(list.files(output,pattern="^susceptibility_linkage_conflict_summary",full.names=TRUE),show_col_types=FALSE)
stopifnot(identical(names(summary),c("metric","n","site_name")),summary$n[summary$metric=="conflicting_organism_ids"]==1)
private_output<-file.path(scratch,"data","intermediate","runs",run,"susceptibility")
stopifnot(length(list.files(private_output,pattern="^organism_id_.*csv$"))==2,
 !length(list.files(output,pattern="^organism_id_")))
stopifnot(read_csv(list.files(output,pattern="^susceptibility_availability",full.names=TRUE),show_col_types=FALSE)$analysis_status=="failed")
stopifnot(any(grepl("Linkage details saved locally",readLines(log))),!any(grepl("reused|p1|h1",readLines(log))))
message("Script 9 conflict diagnostics integration passed; private details stay outside aggregate outputs.")
